    def put(n, goal, guide, head, rows, key, pages, at=None, extra=()):
        tid = f'hn04-T{n:02}'
        source = 'افزودهٔ آموزشی؛ بر پایهٔ ' + pages
        blocks = [
            {'type':'h3','text':'توضیح تکمیلی — نقشهٔ یادگیری'},
            {'type':'p','text':guide,'src':source},
            {'type':'table','head':head,'rows':rows,'caption':'جدول آموزشی — جدا از متن منبع','src':source},
            {'type':'callout','kind':'key','title':'جمع‌بندی آموزشی — نکتهٔ مرور','text':key,'src':source},
            *extra,
        ]
        original = base[n-1]['blocks']
        idx = len(original)-2 if at is None else at
        topics[tid] = {'card_rows':[{'label':'راهبرد مرور','text':goal}], 'after':{str(idx):blocks}}
